  'canvas.mindMapOneSentence.intro': 'ವಿಷಯವನ್ನು ನಮೂದಿಸಿ ಅಥವಾ ಶಾಖೆಗಳ ಸಂಖ್ಯೆ, ವರ್ಗೀಕರಣ ಆಯಾಮಗಳು, ಹಂತಗಳು ಇತ್ಯಾದಿಗಳಂತಹ ರಚನಾತ್ಮಕ ಅವಶ್ಯಕತೆಗಳನ್ನು ವಿವರಿಸಿ.',
