  'canvas.mindMapSideToolbar.outlineIntro': 'ನಕ್ಷೆಯ ರಚನೆಯನ್ನು ಎಡಿಟ್ ಮಾಡಲು ಔಟ್‌ಲೈನ್ ಅನ್ನು ಬಳಸಿ, ಆದೇಶವನ್ನು ಹೊಂದಿಸಲು ಡ್ರ್ಯಾಗ್ ಮತ್ತು ಡ್ರಾಪ್ ಮಾಡಿ ಮತ್ತು ಅವುಗಳನ್ನು ಬ್ಯಾಚ್‌ಗಳಲ್ಲಿ ಸೇರಿಸಲು ಬಹು ಸಾಲುಗಳನ್ನು ಅಂಟಿಸಿ.',
